-- Keep customer artifact objects accessible only through the trusted FastAPI service.
-- Supabase Storage grants CRUD to client roles globally; this bucket-specific RLS
-- denial makes the intended server-only boundary explicit without changing other buckets.
do $$
begin
  if not exists (
    select 1 from storage.buckets
    where id = 'moreai-artifacts' and public = false
  ) then
    raise exception 'moreai_artifacts_bucket_missing_or_public';
  end if;
end
$$;

drop policy if exists moreai_artifacts_storage_server_only on storage.objects;
create policy moreai_artifacts_storage_server_only
  on storage.objects
  for all
  to anon, authenticated
  using (bucket_id = 'moreai-artifacts' and false)
  with check (bucket_id = 'moreai-artifacts' and false);

comment on policy moreai_artifacts_storage_server_only on storage.objects is
  'Deny direct anon/authenticated client access; customer artifact access is mediated by FastAPI using server-only credentials.';

-- Make profile-retention claims retryable after worker/network failures.
-- A five-minute claim lease prevents hot-loop duplicate work while allowing recovery.
alter table public.moreai_browser_sessions
  add column if not exists profile_retention_claimed_at timestamptz;

create index if not exists moreai_browser_sessions_profile_retention_claim_idx
  on public.moreai_browser_sessions(profile_retention_claimed_at, profile_retention_after, id)
  where profile_deleted_at is null and status in ('closed','expired');

create or replace function public.moreai_claim_browser_profile_retention(p_limit integer default 100)
returns jsonb
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_items jsonb;
begin
  if p_limit is null or p_limit < 1 or p_limit > 100 then
    raise exception 'browser_profile_retention_limit_invalid' using errcode='22023';
  end if;

  with candidates as (
    select id, user_id, profile_retention_after, profile_retention_notified_at
    from public.moreai_browser_sessions
    where status in ('closed','expired')
      and profile_retention_after <= now()
      and profile_deleted_at is null
      and (
        profile_retention_claimed_at is null
        or profile_retention_claimed_at <= now() - interval '5 minutes'
      )
    order by profile_retention_after asc, id asc
    for update skip locked
    limit p_limit
  ), updated as (
    update public.moreai_browser_sessions as sessions
    set
      profile_retention_claimed_at=now(),
      profile_retention_notified_at=coalesce(sessions.profile_retention_notified_at, now())
    from candidates
    where sessions.id=candidates.id
    returning sessions.id, sessions.user_id, sessions.profile_retention_after
  ), events as (
    insert into public.moreai_browser_session_events(
      session_id,user_id,event_type,metadata
    )
    select updated.id,updated.user_id,'profile_retention_eligible',
      jsonb_build_object('retention_after',updated.profile_retention_after,'retention_days',30)
    from updated
    join candidates on candidates.id=updated.id
    where candidates.profile_retention_notified_at is null
    returning session_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'session_id',updated.id,
    'user_id',updated.user_id,
    'retention_after',updated.profile_retention_after
  )), '[]'::jsonb)
  into v_items
  from updated;

  return jsonb_build_object('items',v_items,'retention_days',30,'claim_lease_seconds',300);
end;
$function$;

create or replace function public.moreai_ack_browser_profile_deleted(
  p_session_id uuid,
  p_user_id uuid
) returns jsonb
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_row public.moreai_browser_sessions%rowtype;
begin
  if p_session_id is null or p_user_id is null then
    raise exception 'browser_profile_ack_identity_invalid' using errcode='22023';
  end if;

  update public.moreai_browser_sessions
  set profile_deleted_at=now(), profile_retention_claimed_at=null
  where id=p_session_id
    and user_id=p_user_id
    and status in ('closed','expired')
    and profile_deleted_at is null
    and profile_retention_after <= now()
  returning * into v_row;

  if found then
    insert into public.moreai_browser_session_events(
      session_id,user_id,event_type,metadata
    ) values (
      p_session_id,p_user_id,'profile_deleted',
      jsonb_build_object('source','worker','retention_policy_days',30)
    );
    return jsonb_build_object('session_id',p_session_id,'status','profile_deleted');
  end if;

  select * into v_row
  from public.moreai_browser_sessions
  where id=p_session_id and user_id=p_user_id;

  if found and v_row.profile_deleted_at is not null then
    return jsonb_build_object('session_id',p_session_id,'status','profile_deleted','replayed',true);
  end if;

  raise exception 'browser_profile_retention_gate_not_satisfied' using errcode='23514';
end;
$function$;

revoke all on function public.moreai_claim_browser_profile_retention(integer) from public,anon,authenticated;
revoke all on function public.moreai_ack_browser_profile_deleted(uuid,uuid) from public,anon,authenticated;
grant execute on function public.moreai_claim_browser_profile_retention(integer) to service_role;
grant execute on function public.moreai_ack_browser_profile_deleted(uuid,uuid) to service_role;

-- Atomically finalize a browser session close and append its lifecycle event.
-- Callable only by the trusted FastAPI service-role repository.
create or replace function public.moreai_complete_browser_session_close(
  p_session_id uuid, p_user_id uuid
) returns jsonb
language plpgsql security definer set search_path=''
as $function$
declare v_row public.moreai_browser_sessions%rowtype;
begin
  if p_session_id is null or p_user_id is null then
    raise exception 'browser_session_close_identity_invalid' using errcode='22023';
  end if;
  select * into v_row from public.moreai_browser_sessions
  where id=p_session_id and user_id=p_user_id for update;
  if not found then
    raise exception 'browser_session_close_request_not_found' using errcode='P0002';
  end if;
  if v_row.status='closed' then
    return jsonb_build_object('session_id',p_session_id,'status','closed','replayed',true);
  end if;
  if v_row.status<>'close_requested' then
    raise exception 'browser_session_close_request_not_found' using errcode='P0002';
  end if;
  update public.moreai_browser_sessions
  set status='closed',encrypted_state=null,closed_at=now(),
      profile_retention_after=now()+interval '30 days'
  where id=p_session_id and user_id=p_user_id;
  insert into public.moreai_browser_session_events(session_id,user_id,event_type,metadata)
  values(p_session_id,p_user_id,'closed',jsonb_build_object('source','worker_reconciler'));
  return jsonb_build_object('session_id',p_session_id,'status','closed');
end;
$function$;
revoke all on function public.moreai_complete_browser_session_close(uuid,uuid) from public,anon,authenticated;
grant execute on function public.moreai_complete_browser_session_close(uuid,uuid) to service_role;

-- Atomically request browser-session closure and append its lifecycle event.
create or replace function public.moreai_request_browser_session_close(
  p_session_id uuid,
  p_user_id uuid,
  p_source text,
  p_reason text default null
) returns jsonb
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_row public.moreai_browser_sessions%rowtype;
begin
  if p_session_id is null or p_user_id is null
     or p_source not in ('customer','ttl_reconciler','acquire_guard')
     or (p_reason is not null and p_reason not in ('ttl','idle','ttl_or_idle')) then
    raise exception 'browser_session_close_request_invalid' using errcode='22023';
  end if;

  select * into v_row
  from public.moreai_browser_sessions
  where id=p_session_id and user_id=p_user_id
  for update;

  if not found then
    raise exception 'browser_session_not_found' using errcode='P0002';
  end if;

  if v_row.status in ('close_requested','closed') then
    return jsonb_build_object(
      'session_id',p_session_id,'status',v_row.status,'replayed',true
    );
  end if;

  if v_row.status <> 'active' then
    raise exception 'browser_session_not_active' using errcode='P0002';
  end if;

  update public.moreai_browser_sessions
  set status='close_requested'
  where id=p_session_id and user_id=p_user_id;

  insert into public.moreai_browser_session_events(
    session_id,user_id,event_type,metadata
  ) values (
    p_session_id,p_user_id,'close_requested',
    jsonb_strip_nulls(jsonb_build_object('source',p_source,'reason',p_reason))
  );

  return jsonb_build_object('session_id',p_session_id,'status','close_requested');
end;
$function$;

revoke all on function public.moreai_request_browser_session_close(uuid,uuid,text,text)
  from public,anon,authenticated;
grant execute on function public.moreai_request_browser_session_close(uuid,uuid,text,text)
  to service_role;

-- Atomically finalize a worker-owned browser session and append its close event.
create or replace function public.moreai_mark_browser_session_closed(
  p_session_id uuid,
  p_user_id uuid,
  p_run_id uuid
) returns jsonb
language plpgsql security definer set search_path=''
as $function$
declare v_row public.moreai_browser_sessions%rowtype;
begin
  if p_session_id is null or p_user_id is null or p_run_id is null then
    raise exception 'browser_session_close_identity_invalid' using errcode='22023';
  end if;
  select * into v_row from public.moreai_browser_sessions
  where id=p_session_id and user_id=p_user_id for update;
  if not found then
    raise exception 'browser_session_not_found' using errcode='P0002';
  end if;
  if v_row.status='closed' then
    return jsonb_build_object('session_id',p_session_id,'status','closed','replayed',true);
  end if;
  if v_row.status not in ('active','close_requested') then
    raise exception 'browser_session_not_active' using errcode='P0002';
  end if;
  update public.moreai_browser_sessions
  set status='closed',encrypted_state=null,closed_at=now(),
      profile_retention_after=now()+interval '30 days'
  where id=p_session_id and user_id=p_user_id;
  insert into public.moreai_browser_session_events(session_id,user_id,event_type,metadata)
  values(p_session_id,p_user_id,'closed',
    jsonb_build_object('source','worker','run_id',p_run_id));
  return jsonb_build_object('session_id',p_session_id,'status','closed');
end;
$function$;
revoke all on function public.moreai_mark_browser_session_closed(uuid,uuid,uuid)
  from public,anon,authenticated;
grant execute on function public.moreai_mark_browser_session_closed(uuid,uuid,uuid)
  to service_role;

-- Atomic owner-scoped Personal Memory clear.
-- The API supplies the authenticated user ID after customer_principal authorization.
-- All changes below commit or roll back together. Chat messages and citations are preserved.

create or replace function public.moreai_customer_clear_memory_atomic(p_user_id uuid)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $function$
declare
  v_preferences_updated bigint := 0;
  v_memories_deleted bigint := 0;
  v_episodes_cleared bigint := 0;
begin
  if p_user_id is null then
    raise exception 'memory_clear_user_required' using errcode = '22023';
  end if;

  -- Serialize against the create RPC below. If a create already owns this row,
  -- it commits before this clear; otherwise later creates see disabled consent.
  perform 1
    from public.moreai_customer_memory_preferences
   where user_id = p_user_id
   for update;

  update public.moreai_customer_memory_preferences
     set enabled = false,
         disabled_at = now(),
         updated_at = now()
   where user_id = p_user_id;
  get diagnostics v_preferences_updated = row_count;

  delete from public.moreai_customer_memories
   where user_id = p_user_id;
  get diagnostics v_memories_deleted = row_count;

  -- Match the existing API cleanup semantics: remove only episodic-memory
  -- metadata, retaining the original conversation message and all citations.
  update public.conversation_messages
     set metadata = metadata - array[
       'memory_type',
       'memory_scope',
       'workspace_id',
       'episode',
       'episode_expires_at'
     ]::text[]
   where user_id = p_user_id
     and metadata ->> 'memory_type' = 'episodic';
  get diagnostics v_episodes_cleared = row_count;

  return jsonb_build_object(
    'completed', true,
    'consent_disabled', v_preferences_updated > 0,
    'memories_deleted', v_memories_deleted,
    'episodes_cleared', v_episodes_cleared
  );
end;
$function$;

revoke all on function public.moreai_customer_clear_memory_atomic(uuid)
  from public, anon, authenticated;
grant execute on function public.moreai_customer_clear_memory_atomic(uuid)
  to service_role;


-- Serialize explicit Personal Memory creation with the atomic clear operation.
create or replace function public.moreai_customer_create_personal_memory(
  p_user_id uuid,
  p_consent_version text,
  p_title text,
  p_content text,
  p_retention_days integer
)
returns setof public.moreai_customer_memories
language plpgsql
security invoker
set search_path = ''
as $function$
declare
  v_enabled boolean;
  v_consent_version text;
begin
  if p_user_id is null
     or p_consent_version is null
     or p_title is null
     or p_content is null
     or length(btrim(p_title)) not between 1 and 120
     or length(btrim(p_content)) not between 1 and 4000
     or p_retention_days not in (30, 90, 180, 365) then
    raise exception 'personal_memory_arguments_invalid' using errcode = '22023';
  end if;

  select enabled, consent_version
    into v_enabled, v_consent_version
    from public.moreai_customer_memory_preferences
   where user_id = p_user_id
   for update;

  if not found or not v_enabled or v_consent_version <> p_consent_version then
    raise exception 'personal_memory_consent_required' using errcode = '42501';
  end if;

  return query
  insert into public.moreai_customer_memories (
    user_id, title, content, source_type, scope, expires_at
  ) values (
    p_user_id,
    btrim(p_title),
    btrim(p_content),
    'user_created',
    'personal',
    now() + (p_retention_days * interval '1 day')
  )
  returning *;
end;
$function$;

revoke all on function public.moreai_customer_create_personal_memory(uuid, text, text, text, integer)
  from public, anon, authenticated;
grant execute on function public.moreai_customer_create_personal_memory(uuid, text, text, text, integer)
  to service_role;


-- Disabling Memory consent is distinct from clearing user-authored memories:
-- preserve personal memory items but atomically strip episodic summaries.
create or replace function public.moreai_customer_disable_memory_consent_atomic(
  p_user_id uuid,
  p_consent_version text
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $function$
declare
  v_preference public.moreai_customer_memory_preferences%rowtype;
  v_episodes_cleared bigint := 0;
begin
  if p_user_id is null
     or p_consent_version is null
     or length(p_consent_version) not between 1 and 40 then
    raise exception 'memory_consent_arguments_invalid' using errcode = '22023';
  end if;

  insert into public.moreai_customer_memory_preferences (
    user_id, enabled, consent_version, disabled_at, updated_at
  ) values (
    p_user_id, false, p_consent_version, now(), now()
  )
  on conflict (user_id) do update set
    enabled = false,
    consent_version = excluded.consent_version,
    disabled_at = now(),
    updated_at = now()
  returning * into v_preference;

  update public.conversation_messages
     set metadata = metadata - array[
       'memory_type',
       'memory_scope',
       'workspace_id',
       'episode',
       'episode_expires_at'
     ]::text[]
   where user_id = p_user_id
     and metadata ->> 'memory_type' = 'episodic';
  get diagnostics v_episodes_cleared = row_count;

  return jsonb_build_object(
    'enabled', v_preference.enabled,
    'consent_version', v_preference.consent_version,
    'consented_at', v_preference.consented_at,
    'disabled_at', v_preference.disabled_at,
    'updated_at', v_preference.updated_at,
    'episodes_cleared', v_episodes_cleared
  );
end;
$function$;

revoke all on function public.moreai_customer_disable_memory_consent_atomic(uuid, text)
  from public, anon, authenticated;
grant execute on function public.moreai_customer_disable_memory_consent_atomic(uuid, text)
  to service_role;

-- Enforce the MoreAI browser-to-FastAPI-only business-data boundary explicitly.
-- These tables are accessed through FastAPI/service_role; browser clients must not
-- query them directly. RLS was already enabled; policies make the deny intent explicit.

do $$
declare
  v_table text;
  v_policy text;
  v_tables text[] := array[
    'learning_assessments',
    'learning_enrollments',
    'learning_lesson_versions',
    'learning_lessons',
    'learning_modules',
    'learning_paths',
    'learning_progress',
    'learning_quiz_attempts',
    'learning_quizzes',
    'learning_run_artifacts',
    'moreai_browser_action_receipts',
    'moreai_browser_session_events',
    'moreai_browser_sessions',
    'moreai_computer_action_receipts',
    'moreai_customer_agent_configs',
    'moreai_worker_capability_snapshots'
  ];
begin
  foreach v_table in array v_tables loop
    if not exists (
      select 1
      from pg_class c
      join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='public'
        and c.relname=v_table
        and c.relkind='r'
        and c.relrowsecurity
    ) then
      raise exception 'server_only_rls_table_missing_or_rls_disabled: %', v_table;
    end if;

    v_policy := 'moreai_deny_client_' || v_table;
    execute format('drop policy if exists %I on public.%I', v_policy, v_table);
    execute format(
      'create policy %I on public.%I for all to anon, authenticated using (false) with check (false)',
      v_policy, v_table
    );
    execute format(
      'comment on policy %I on public.%I is %L',
      v_policy, v_table,
      'Explicitly deny browser anon/authenticated access; all application data/actions are mediated by the trusted FastAPI service.'
    );
  end loop;
end
$$;

-- Shared tenant/global admission leases for the OpenFuse persistent browser runtime.
-- A single transaction-scoped advisory lock serializes admission across API/worker replicas.

create table if not exists public.moreai_browser_capacity_leases (
  session_id uuid primary key references public.moreai_browser_sessions(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  worker_id text not null,
  lease_token uuid not null default gen_random_uuid(),
  expires_at timestamptz not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint moreai_browser_capacity_worker_id_check
    check (worker_id ~ '^[A-Za-z0-9._:-]{1,128}$')
);

create index if not exists moreai_browser_capacity_leases_active_idx
  on public.moreai_browser_capacity_leases(expires_at, user_id, session_id);

alter table public.moreai_browser_capacity_leases enable row level security;
revoke all on table public.moreai_browser_capacity_leases from anon, authenticated;
grant all on table public.moreai_browser_capacity_leases to service_role;

drop policy if exists moreai_deny_client_browser_capacity_leases
  on public.moreai_browser_capacity_leases;
create policy moreai_deny_client_browser_capacity_leases
  on public.moreai_browser_capacity_leases
  for all to anon, authenticated
  using (false) with check (false);

comment on table public.moreai_browser_capacity_leases is
  'Short-lived shared admission leases for OpenFuse browser sessions; accessed only by trusted FastAPI service role.';

create or replace function public.moreai_acquire_browser_capacity_lease(
  p_session_id uuid,
  p_user_id uuid,
  p_worker_id text,
  p_lease_seconds integer default 300
) returns jsonb
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_session public.moreai_browser_sessions%rowtype;
  v_lease public.moreai_browser_capacity_leases%rowtype;
  v_global_count integer;
  v_user_count integer;
  v_token uuid;
  v_expiry timestamptz;
begin
  if p_session_id is null or p_user_id is null
     or p_worker_id is null or p_worker_id !~ '^[A-Za-z0-9._:-]{1,128}$'
     or p_lease_seconds is null or p_lease_seconds not between 60 and 900 then
    raise exception 'browser_capacity_lease_arguments_invalid' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('moreai_browser_capacity_global', 0));

  select * into v_session
  from public.moreai_browser_sessions
  where id=p_session_id and user_id=p_user_id and status='active'
  for update;

  if not found then
    return jsonb_build_object('acquired',false,'reason','session_not_active');
  end if;

  select * into v_lease
  from public.moreai_browser_capacity_leases
  where session_id=p_session_id
  for update;

  if found and v_lease.user_id=p_user_id and v_lease.expires_at>now() then
    update public.moreai_browser_capacity_leases
    set worker_id=p_worker_id, expires_at=now()+(p_lease_seconds * interval '1 second'), updated_at=now()
    where session_id=p_session_id
    returning lease_token, expires_at into v_token, v_expiry;
    return jsonb_build_object('acquired',true,'lease_token',v_token,'expires_at',v_expiry,'reused',true);
  end if;

  delete from public.moreai_browser_capacity_leases
  where expires_at<=now();

  select count(*)::integer into v_global_count
  from public.moreai_browser_capacity_leases
  where expires_at>now();

  select count(*)::integer into v_user_count
  from public.moreai_browser_capacity_leases
  where user_id=p_user_id and expires_at>now();

  if v_global_count>=24 then
    return jsonb_build_object('acquired',false,'reason','global_capacity_limit','limit',24);
  end if;
  if v_user_count>=2 then
    return jsonb_build_object('acquired',false,'reason','tenant_capacity_limit','limit',2);
  end if;

  insert into public.moreai_browser_capacity_leases(
    session_id,user_id,worker_id,lease_token,expires_at
  ) values (
    p_session_id,p_user_id,p_worker_id,gen_random_uuid(),now()+(p_lease_seconds * interval '1 second')
  )
  on conflict(session_id) do update set
    user_id=excluded.user_id,
    worker_id=excluded.worker_id,
    lease_token=excluded.lease_token,
    expires_at=excluded.expires_at,
    updated_at=now()
  returning lease_token,expires_at into v_token,v_expiry;

  return jsonb_build_object('acquired',true,'lease_token',v_token,'expires_at',v_expiry,'reused',false);
end;
$function$;

revoke all on function public.moreai_acquire_browser_capacity_lease(uuid,uuid,text,integer)
  from public,anon,authenticated;
grant execute on function public.moreai_acquire_browser_capacity_lease(uuid,uuid,text,integer)
  to service_role;

-- Release capacity in the same transaction that marks a browser session closed.
create or replace function public.moreai_complete_browser_session_close(
  p_session_id uuid, p_user_id uuid
) returns jsonb
language plpgsql security definer set search_path=''
as $function$
declare v_row public.moreai_browser_sessions%rowtype;
begin
  if p_session_id is null or p_user_id is null then
    raise exception 'browser_session_close_identity_invalid' using errcode='22023';
  end if;
  select * into v_row from public.moreai_browser_sessions
  where id=p_session_id and user_id=p_user_id for update;
  if not found then
    raise exception 'browser_session_close_request_not_found' using errcode='P0002';
  end if;
  if v_row.status='closed' then
    delete from public.moreai_browser_capacity_leases where session_id=p_session_id and user_id=p_user_id;
    return jsonb_build_object('session_id',p_session_id,'status','closed','replayed',true);
  end if;
  if v_row.status<>'close_requested' then
    raise exception 'browser_session_close_request_not_found' using errcode='P0002';
  end if;
  update public.moreai_browser_sessions
  set status='closed',encrypted_state=null,closed_at=now(),
